const state = $input.first().json;
if (!state.runId || !state.orgId || state.records.length !== 3) throw new Error('Unexpected Salesforce local run.');
const supported = ['Lead', 'Opportunity', 'Case'];
if (new Set(state.records.map(record => record.object)).size !== 3) throw new Error('Expected three Salesforce objects.');
return state.records.map(record => {
  if (!supported.includes(record.object) || record.revision !== 1) throw new Error('Unexpected authoritative record.');
  const event = {
    orgId: state.orgId,
    entityName: record.object,
    recordId: record.id,
    transactionKey: 'n8n-revenueos-' + state.runId,
    sequenceNumber: 1,
    replayId: 'n8n-local-' + record.object,
    expectedRevision: record.revision,
    changeType: 'UPDATE',
  };
  return { json: { object: record.object, request: { runId: state.runId, event } } };
});

const requests = $('Build normalized events').all();
return $input.all().map((item, index) => {
  const original = requests[index].json;
  const first = item.json;
  if (first.runId !== original.request.runId || first.recordId !== original.request.event.recordId ||
      first.before.object !== original.object || first.status !== 'pending_review' || first.localEffects !== 0) {
    throw new Error('Proposal does not match its authoritative record.');
  }
  return { json: { ...original, first } };
});

const attempts = $('Keep replay evidence').all();
const fields = ['receiptId', 'runId', 'recordId', 'status', 'before', 'patch', 'expectedRevision', 'sourceHash', 'reviewer', 'attempts', 'localEffects', 'history', 'reasons'];
return $input.all().map((item, index) => {
  const first = attempts[index].json.first;
  const replay = item.json;
  if (replay.replayed !== true || fields.some(field => JSON.stringify(first[field]) !== JSON.stringify(replay[field])) ||
      replay.status !== 'pending_review' || replay.localEffects !== 0 || replay.attempts !== 0 || replay.reviewer !== null) {
    throw new Error('Replay changed a proposal or produced an effect.');
  }
  return { json: {
    object: replay.before.object,
    runId: replay.runId,
    receiptId: replay.receiptId,
    recordId: replay.recordId,
    status: replay.status,
    localEffects: replay.localEffects,
    attempts: replay.attempts,
    patch: replay.patch,
    sameReceipt: true,
    reviewRequired: true,
    scope: 'Synthetic local Salesforce proposal. Every workflow invocation creates a fresh run.',
  } };
});
